"use client";

import { useMemo } from 'react';
import {
  ReactFlow,
  Controls,
  Background,
  applyNodeChanges,
  applyEdgeChanges,
  Node,
  Edge,
  NodeChange,
  EdgeChange,
} from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import { GraphData } from '@/lib/mockData';

// Custom nodes can be implemented here later for more complex designs
// For now, we will use basic node styling via the standard ReactFlow node type

interface Props {
  data: GraphData | null;
}

export default function InvestigationGraph({ data }: Props) {
  // Convert our mock data format to React Flow format
  // We're calculating some initial positions based on a simple layout
  const initialNodes: Node[] = useMemo(() => {
    if (!data) return [];
    
    return data.nodes.map((n, i) => {
      // Basic layout logic: Target on left, VASP on right, others in middle
      let x = 400;
      let y = 100 + i * 100;
      
      if (n.type === 'target') {
        x = 50;
        y = 250;
      } else if (n.type === 'cluster') {
        x = 350;
        y = 250;
      } else if (n.type === 'vasp') {
        x = 750;
        y = 250;
      } else {
        x = 550;
        y = 100 + (i % 2) * 200; // stagger standard nodes
      }

      // Determine styling based on type
      let bgColor = '#1e293b';
      let borderColor = '#334155';
      let color = '#f8fafc';

      if (n.type === 'target') {
        bgColor = '#ef4444'; // Red
        borderColor = '#b91c1c';
      } else if (n.type === 'vasp') {
        bgColor = '#10b981'; // Green
        borderColor = '#047857';
      } else if (n.type === 'cluster') {
        bgColor = '#3b82f6'; // Blue
        borderColor = '#1d4ed8';
      }

      return {
        id: n.id,
        position: { x, y },
        data: { label: n.label },
        style: {
          background: bgColor,
          color: color,
          border: `2px solid ${borderColor}`,
          borderRadius: '8px',
          padding: '10px 15px',
          fontWeight: 'bold',
          width: 180,
          textAlign: 'center' as const,
        }
      };
    });
  }, [data]);

  const initialEdges: Edge[] = useMemo(() => {
    if (!data) return [];
    return data.edges.map(e => ({
      id: e.id,
      source: e.source,
      target: e.target,
      label: e.label,
      animated: true,
      style: { stroke: '#94a3b8', strokeWidth: 2 },
      labelStyle: { fill: '#cbd5e1', fontWeight: 'bold' },
      labelBgStyle: { fill: '#1e293b' }
    }));
  }, [data]);

  if (!data) {
    return (
      <div className="flex-1 flex items-center justify-center bg-slate-900 border border-slate-700 rounded-lg">
        <p className="text-slate-400">Enter a Bitcoin address to begin tracing.</p>
      </div>
    );
  }

  return (
    <div className="flex-1 w-full h-full bg-slate-900 border border-slate-700 rounded-lg overflow-hidden">
      <ReactFlow
        nodes={initialNodes}
        edges={initialEdges}
        fitView
        colorMode="dark"
      >
        <Background color="#334155" gap={20} />
        <Controls className="react-flow__controls" />
      </ReactFlow>
    </div>
  );
}
